package com.midroid.masarifi.data.mm

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.math.BigDecimal
import java.time.LocalDateTime

/** Uses the synthetic fixture generated by tools/gen_mm_fixture.py (fake data, real Money Manager column layout). */
class MoneyManagerParserTest {
    private fun bytes(name: String) = javaClass.classLoader!!.getResourceAsStream("mm/$name")!!.readBytes()

    private fun check(r: MmParseResult, withMillis: Boolean) {
        assertEquals(16, r.dataRows)
        assertEquals("OMR", r.mainCurrency)
        assertEquals(1, r.headerRow)
        assertEquals(13, r.txns.size)
        assertEquals(2, r.skipped.size)
        assertEquals(r.dataRows, r.consumedRows + r.skipped.size) // nothing dropped silently
        assertEquals(listOf(MmSkipReason.BAD_DATE, MmSkipReason.UNKNOWN_TYPE), r.skipped.map { it.reason })
        assertEquals(listOf(15, 17), r.skipped.map { it.row })

        assertEquals(2, r.txns.count { it.kind == MmKind.INCOME })
        assertEquals(9, r.txns.count { it.kind == MmKind.EXPENSE })
        assertEquals(0L, r.txns.single { it.note == "zero" }.amountMilli) // zero-amount rows are kept
        assertEquals(2, r.txns.count { it.kind == MmKind.TRANSFER })

        // Transfer-Out + Transfer-In pair becomes ONE transfer Bank Muscat → Cash
        val atm = r.txns.single { it.kind == MmKind.TRANSFER && it.note == "ATM" }
        assertEquals("Bank Muscat", atm.account)
        assertEquals("Cash", atm.toAccount)
        assertEquals(50_000L, atm.amountMilli)
        assertEquals(listOf(5, 6), atm.rows)
        assertEquals("", atm.category)
        // Unpaired Transfer-Out: destination comes from the Category column
        val unpaired = r.txns.single { it.kind == MmKind.TRANSFER && it.note == "" }
        assertEquals("Savings", unpaired.account)
        assertEquals("Bank Muscat", unpaired.toAccount)

        val food = r.txns.first { it.note == "شاورما" }
        assertEquals(MmKind.EXPENSE, food.kind)
        assertEquals(1_500L, food.amountMilli)
        assertEquals("Cash", food.account)
        assertEquals("Food", food.category)
        assertEquals(LocalDateTime.of(2024, 3, 31, 21, 5, 10, if (withMillis) 250_000_000 else 0), food.dateTime)

        val dateOnly = r.txns.first { it.category == "Grecory" }
        assertEquals(LocalDateTime.of(2024, 3, 28, 0, 0), dateOnly.dateTime)
        assertEquals(12_250L, dateOnly.amountMilli)

        val phone = r.txns.first { it.note == "سماعة" }
        assertEquals("Electronics", phone.category) // trailing space trimmed
        assertEquals("Phone", phone.subcategory)
        assertEquals("Online order", phone.description)

        val hotel = r.txns.first { it.note == "Hotel" }
        assertEquals(38_450L, hotel.amountMilli) // main-currency (OMR) column used
        assertEquals("USD", hotel.originalCurrency)
        assertEquals("100", hotel.originalAmount)
        assertNull(food.originalCurrency)

        // identical rows are both kept with distinct, stable hashes
        val dups = r.txns.filter { it.note == "duplicate-looking" }
        assertEquals(2, dups.size)
        assertEquals(13, r.txns.map { it.hash }.toSet().size)
        assertTrue(r.txns.all { it.hash.startsWith("mm:") })
    }

    @Test fun parsesXlsxFixture() {
        val r = MoneyManagerParser.parseFile(bytes("money_manager_sample.xlsx"))
        check(r, withMillis = true)
        assertEquals(r.txns.map { it.hash }, MoneyManagerParser.parseFile(bytes("money_manager_sample.xlsx")).txns.map { it.hash })
    }

    @Test fun parsesCsvFixture() = check(MoneyManagerParser.parseFile(bytes("money_manager_sample.csv")), withMillis = false)

    @Test fun excelSerialDates() {
        assertEquals(LocalDateTime.of(2025, 12, 31, 0, 0), XlsxReader.serialToDateTime(46022.0))
        assertEquals(LocalDateTime.of(2024, 3, 20, 18, 30), XlsxReader.serialToDateTime(45371.0 + 18.5 / 24))
    }

    @Test fun amountParsing() {
        assertEquals(BigDecimal("1234.5"), MoneyManagerParser.parseAmount(SheetCell("1,234.5")))
        assertEquals(BigDecimal("1234.5"), MoneyManagerParser.parseAmount(SheetCell("1.234,5")))
        assertEquals(BigDecimal("-3.250"), MoneyManagerParser.parseAmount(SheetCell("OMR -3.250")))
        assertEquals(BigDecimal("4.3"), MoneyManagerParser.parseAmount(SheetCell("٤٫٣")))
        assertNull(MoneyManagerParser.parseAmount(SheetCell("")))
    }

    @Test fun stringDates() {
        assertNotNull(MoneyManagerParser.parseDate(SheetCell("12/31/2025 11:18:49")))
        assertEquals(LocalDateTime.of(2025, 1, 2, 0, 0), MoneyManagerParser.parseDate(SheetCell("2025-01-02")))
    }

    @Test(expected = MmFormatException::class)
    fun rejectsLegacyXls() { MoneyManagerParser.parseFile(byteArrayOf(0xD0.toByte(), 0xCF.toByte(), 0x11, 0xE0.toByte(), 0, 0)) }
}
